9	use alloy::providers::{Provider, DynProvider};
10	use alloy::network::Ethereum;
11	use alloy::rpc::types::Block;
12	use tokio::time::{sleep, Duration};
13	use tracing::warn;
14	
15	/// Backoff applied *before* each retry; the number of attempts is one more than
16	/// the number of delays (initial call + one retry per delay).
17	const RPC_RETRY_DELAYS: [Duration; 3] = [
18	    Duration::from_secs(5),
19	    Duration::from_secs(15),
20	    Duration::from_secs(45),
21	];
22	
23	const RPC_MAX_ATTEMPTS: usize = RPC_RETRY_DELAYS.len() + 1;
24	
25	pub(crate) const RECEIPT_TIMEOUT: Duration = Duration::from_secs(120);
26	
27	/// Percentage a replacement transaction must reach relative to the one it replaces.
28	///
29	/// Geth's default `--txpool.pricebump` is 10%, applied to `maxFeePerGas` and
30	/// `maxPriorityFeePerGas` independently - bumping only one is rejected. 112 leaves
31	/// headroom for integer truncation and for nodes configured above the default.
32	const FEE_BUMP_PERCENT: u128 = 112;
33	
34	/// Ceiling on a replacement fee, as a multiple of the current market estimate.
35	/// Resending every dispatcher cycle compounds, so escalation has to stop somewhere.
36	const FEE_CEILING_MULTIPLE: u128 = 4;
37	
38	/// Fee for a replacement transaction: at least `FEE_BUMP_PERCENT` of what the stuck
39	/// transaction paid (or the node rejects it as underpriced), and at least the current
40	/// market rate (or it clears the mempool's rule but still will not be mined).
41	///
42	/// Returns `None` once the result would exceed the ceiling, meaning: stop bumping and
43	/// keep waiting. The last replacement stays in the mempool and remains mineable, so
44	/// the deposit is never at risk of being spent twice however long it takes.
45	pub(crate) fn bumped_fee(previous: u128, market_estimate: u128) -> Option<u128> {
46	    let bumped = (previous.saturating_mul(FEE_BUMP_PERCENT) / 100).max(market_estimate);
47	    let ceiling = market_estimate.saturating_mul(FEE_CEILING_MULTIPLE);
48	    (bumped <= ceiling).then_some(bumped)
49	}
50	
51	/// Retries `f` with [`RPC_RETRY_DELAYS`] backoff, returning the last error if every
52	/// attempt fails. Callers decide what a failure means: startup paths that cannot
53	/// continue should use [`retry_rpc_or_panic`], while long-running loops should
54	/// handle the error and keep going.
55	pub(crate) async fn retry_rpc<T, E, F, Fut>(op_name: impl std::fmt::Display, mut f: F) -> Result<T, E>
56	where
57	    F: FnMut() -> Fut,
58	    Fut: std::future::Future<Output = Result<T, E>>,
59	    E: std::fmt::Display,
60	{
61	    for attempt in 0..RPC_MAX_ATTEMPTS {
62	        match f().await {
63	            Ok(v) => return Ok(v),
64	            Err(e) => match RPC_RETRY_DELAYS.get(attempt) {
65	                Some(delay) => {
66	                    warn!(logger = "RPC", op = %op_name, attempt = attempt + 1, "{op_name} failed: {e}, retrying...");
67	                    sleep(*delay).await;
68	                }
69	                None => return Err(e),
70	            },
71	        }
72	    }
73	    unreachable!()
74	}
75	
76	/// Like [`retry_rpc`], but also retries when the node answers `null`.
77	///
78	/// A node that is behind or mid-sync can return `null` for a block that does exist,
79	/// and with several transports racing it is often the fastest to answer — there is
80	/// no block to fetch. Treating that as success hands `None` straight to callers that
81	/// panic on it, when a single retry would usually have cleared it.
82	pub(crate) async fn retry_rpc_opt<T, E, F, Fut>(op_name: impl std::fmt::Display, mut f: F) -> Result<Option<T>, E>
83	where
84	    F: FnMut() -> Fut,
85	    Fut: std::future::Future<Output = Result<Option<T>, E>>,
86	    E: std::fmt::Display,
87	{
88	    for attempt in 0..RPC_MAX_ATTEMPTS {
89	        let result = f().await;
90	        if let Ok(Some(_)) = &result {
91	            return result;
92	        }
93	        match RPC_RETRY_DELAYS.get(attempt) {
94	            Some(delay) => {
95	                match &result {
96	                    Ok(_) => warn!(logger = "RPC", op = %op_name, attempt = attempt + 1, "{op_name} returned null, retrying..."),
97	                    Err(e) => warn!(logger = "RPC", op = %op_name, attempt = attempt + 1, "{op_name} failed: {e}, retrying..."),
98	                }
99	                sleep(*delay).await;
100	            }
101	            None => return result,
102	        }
103	    }
104	    unreachable!()
105	}
106	
107	/// Fail-fast wrapper around [`retry_rpc`] for paths where there is no meaningful
108	/// way to continue (startup checks, config loading).
109	pub(crate) async fn retry_rpc_or_panic<T, E, F, Fut>(op_name: impl std::fmt::Display, f: F) -> T
110	where
111	    F: FnMut() -> Fut,
112	    Fut: std::future::Future<Output = Result<T, E>>,
113	    E: std::fmt::Display,
114	{
115	    retry_rpc(&op_name, f)
116	        .await
117	        .unwrap_or_else(|e| panic!("Failed to {op_name} after {RPC_MAX_ATTEMPTS} attempts: {e}"))
118	}
119	
120	async fn get_block_with_retry(provider: &DynProvider<Ethereum>, block_num: alloy::eips::BlockNumberOrTag) -> Block {
121	    retry_rpc_opt(std::fmt::from_fn(|f| write!(f, "get block {block_num}")), || async { provider.get_block_by_number(block_num).await }).await
122	        .unwrap_or_else(|e| panic!("Failed to get block {block_num}: {e}"))
123	        .unwrap_or_else(|| panic!("Block {block_num} not found"))
124	}
