27	fn decode_revert_reason(err_msg: &str) -> Option<String> {
28	    let data_prefix = "data: \"0x";
29	    let start = err_msg.find(data_prefix)? + data_prefix.len();
30	    let end = err_msg[start..].find('"')? + start;
31	    let hex_data = &err_msg[start..end];
32	
33	    if hex_data.is_empty() {
34	        return Some("(empty)".to_string());
35	    }
36	
37	    if hex_data.len() < 8 {
38	        return Some(format!("0x{}", hex_data));
39	    }
40	
41	    let bytes = alloy::hex::decode(hex_data).ok()?;
42	
43	    if bytes.len() >= 4 && bytes[0..4] == [0x08, 0xc3, 0x79, 0xa0] {
44	        if bytes.len() >= 68 {
45	            let offset =
46	                u32::from_be_bytes([bytes[4 + 28], bytes[4 + 29], bytes[4 + 30], bytes[4 + 31]])
47	                    as usize;
48	            if bytes.len() >= 36 + offset {
49	                let len_start = 4 + offset;
50	                let len = u32::from_be_bytes([
51	                    bytes[len_start + 28],
52	                    bytes[len_start + 29],
53	                    bytes[len_start + 30],
54	                    bytes[len_start + 31],
55	                ]) as usize;
56	                let str_start = len_start + 32;
57	                if bytes.len() >= str_start + len {
58	                    return String::from_utf8(bytes[str_start..str_start + len].to_vec()).ok();
59	                }
60	            }
61	        }
62	    }
63	
64	    if bytes.len() >= 4 && bytes[0..4] == [0x4e, 0x48, 0x7b, 0x71] {
65	        if bytes.len() >= 36 {
66	            let code = U256::from_be_slice(&bytes[4..36]);
67	            return Some(format!("Panic(0x{:02x})", code));
68	        }
69	    }
70	
71	    if bytes.len() >= 4 {
72	        let selector: [u8; 4] = bytes[0..4].try_into().unwrap();
73	        let known_errors: &[(&str, usize)] = &[
74	            ("UnknownRoot(bytes32)", 32),
75	            ("AlreadySpent()", 0),
76	            ("ProofTooLong(uint256)", 32),
77	            ("NotOutbox(address)", 32),
78	        ];
79	        for (sig, param_len) in known_errors {
80	            let expected = &alloy::primitives::keccak256(sig)[..4];
81	            if selector == expected {
82	                if *param_len == 0 {
83	                    return Some(sig.to_string());
84	                } else if bytes.len() >= 4 + param_len {
85	                    return Some(format!(
86	                        "{}(0x{})",
87	                        sig.split('(').next().unwrap(),
88	                        alloy::hex::encode(&bytes[4..4 + param_len])
89	                    ));
90	                }
91	            }
92	        }
93	    }
94	
95	    Some(format!("0x{}", hex_data))
96	}
