128	/// The lowest nonce this account has broadcast but not had confirmed, if any.
129	///
130	/// A fee bump only helps the transaction sitting at this nonce; anything numbered
131	/// above it cannot be mined until that one clears, so bumping those overpays without
132	/// unblocking anything.
133	///
134	/// Approximate by nature - mempool contents are node-local and `FallbackService` races
135	/// several transports - so this is used only to avoid pointless bumps, never as the
136	/// safety mechanism. Preventing a duplicate send is the pinned nonce's job, and that
137	/// never consults the mempool.
138	pub async fn blocking_nonce(provider: &DynProvider<Ethereum>, address: Address) -> Option<u64> {
139	    let confirmed = provider
140	        .get_transaction_count(address)
141	        .latest()
142	        .await
143	        .ok()?;
144	    let pending = provider
145	        .get_transaction_count(address)
146	        .pending()
147	        .await
148	        .ok()?;
149	    (pending > confirmed).then_some(confirmed)
150	}
