152	/// Send `call`, or replace this task's in-flight transaction with a fee-bumped one at
153	/// the same nonce.
154	///
155	/// The nonce is pinned on every send, not just replacements. Pinning bypasses alloy's
156	/// `NonceFiller` (its `status()` returns `Finished` once a nonce is set), which is
157	/// correct for a replacement - it reuses a slot rather than claiming a new one - and
158	/// on a first send it means the nonce is known *before* broadcasting. Reading it back
159	/// afterwards would be unreliable: a node that has not yet seen the transaction answers
160	/// null, and losing the nonce would let the next cycle send a duplicate, which is the
161	/// exact failure this function exists to prevent.
162	pub async fn send_or_replace<P, D>(
163	    call: alloy::contract::CallBuilder<P, D, Ethereum>,
164	    provider: &DynProvider<Ethereum>,
165	    wallet_address: Address,
166	    task_store: &Arc<Mutex<TaskStore>>,
167	    epoch: u64,
168	    action: &str,
169	    route_name: &str,
170	) -> Result<(), Box<dyn std::error::Error + Send + Sync>>
171	where
172	    P: Provider<Ethereum>,
173	    D: alloy::contract::CallDecoder,
174	{
175	    let key = pending_key(action, epoch);
176	    let market = provider.estimate_eip1559_fees().await?;
177	
178	    // Bound to a local so the `MutexGuard` is dropped here rather than being held
179	    // across the awaits below, which would make this future non-`Send`.
180	    let existing = task_store.lock().unwrap().get_pending_tx(&key);
181	
182	    let (nonce, max_fee, priority_fee) = match existing {
183	        Some(previous) => {
184	            let nonce = previous.nonce;
185	            if let Some(blocking) = blocking_nonce(provider, wallet_address).await {
186	                if blocking != nonce {
187	                    info!(
188	                        logger = "Task",
189	                        route = route_name,
190	                        action,
191	                        nonce,
192	                        blocking,
193	                        "Queued behind an earlier nonce, waiting"
194	                    );
195	                    return Err("PendingReplacement".into());
196	                }
197	            }
198	            match (
199	                crate::bumped_fee(previous.max_fee, market.max_fee_per_gas),
200	                crate::bumped_fee(previous.priority_fee, market.max_priority_fee_per_gas),
201	            ) {
202	                (Some(max_fee), Some(priority_fee)) => {
203	                    info!(
204	                        logger = "Task",
205	                        route = route_name,
206	                        action,
207	                        nonce,
208	                        max_fee,
209	                        "Replacing pending tx with a higher fee"
210	                    );
211	                    (nonce, max_fee, priority_fee)
212	                }
213	                _ => {
214	                    warn!(
215	                        logger = "Task",
216	                        route = route_name,
217	                        action,
218	                        nonce,
219	                        "Fee ceiling reached, holding rather than bumping further"
220	                    );
221	                    return Err("PendingReplacement".into());
222	                }
223	            }
224	        }
225	        None => {
226	            let nonce = provider
227	                .get_transaction_count(wallet_address)
228	                .pending()
229	                .await?;
230	            (
231	                nonce,
232	                market.max_fee_per_gas,
233	                market.max_priority_fee_per_gas,
234	            )
235	        }
236	    };
237	
238	    task_store
239	        .lock()
240	        .unwrap()
241	        .set_pending_tx(&key, nonce, max_fee, priority_fee);
242	
243	    let sent = call
244	        .nonce(nonce)
245	        .max_fee_per_gas(max_fee)
246	        .max_priority_fee_per_gas(priority_fee)
247	        .send()
248	        .await;
249	
250	    let pending = match sent {
251	        Ok(pending) => pending,
252	        Err(e) => {
253	            let msg = e.to_string();
254	            if msg.contains("nonce too low") {
255	                info!(
256	                    logger = "Task",
257	                    route = route_name,
258	                    action,
259	                    nonce,
260	                    "Nonce already consumed, deferring to on-chain checks"
261	                );
262	                task_store.lock().unwrap().clear_pending_tx(&key);
263	                return Err("NonceConsumed".into());
264	            }
265	            if msg.contains("replacement transaction underpriced") {
266	                warn!(
267	                    logger = "Task",
268	                    route = route_name,
269	                    action,
270	                    nonce,
271	                    "Replacement underpriced, bumping further next cycle"
272	                );
273	                return Err("PendingReplacement".into());
274	            }
275	            // Anything else may or may not have reached a mempool, so the record stays:
276	            // a stale one is harmless, a lost one risks a duplicate.
277	            return send_tx(Err(e), action, route_name).await;
278	        }
279	    };
280	
281	    match pending
282	        .with_timeout(Some(RECEIPT_TIMEOUT))
283	        .get_receipt()
284	        .await
285	    {
286	        Ok(receipt) => {
287	            task_store.lock().unwrap().clear_pending_tx(&key);
288	            if !receipt.status() {
289	                return Err(format!("[{}] {} reverted", route_name, action).into());
290	            }
291	            info!(
292	                logger = "Task",
293	                route = route_name,
294	                action,
295	                "Transaction succeeded"
296	            );
297	            Ok(())
298	        }
299	        Err(e) => {
300	            warn!(
301	                logger = "Task",
302	                route = route_name,
303	                action,
304	                nonce,
305	                "Receipt not seen ({e}), will replace next cycle"
306	            );
307	            Err("PendingReplacement".into())
308	        }
309	    }
310	}
