312	pub async fn send_tx(
313	    result: Result<PendingTransactionBuilder<Ethereum>, ContractError>,
314	    action: &str,
315	    route_name: &str,
316	) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
317	    match result {
318	        Ok(pending) => {
319	            let receipt = pending
320	                .with_timeout(Some(RECEIPT_TIMEOUT))
321	                .get_receipt()
322	                .await?;
323	            if !receipt.status() {
324	                return Err(format!("[{}] {} reverted", route_name, action).into());
325	            }
326	            info!(
327	                logger = "Task",
328	                route = route_name,
329	                action,
330	                "Transaction succeeded"
331	            );
332	            Ok(())
333	        }
334	        Err(e) => {
335	            let err_msg = e.to_string();
336	            match decode_revert_reason(&err_msg) {
337	                Some(reason) => {
338	                    error!(
339	                        logger = "Task",
340	                        route = route_name,
341	                        action,
342	                        reason = reason.as_str(),
343	                        "Transaction reverted"
344	                    );
345	                    Err(format!("[{}] {} reverted: {}", route_name, action, reason).into())
346	                }
347	                None => Err(e.into()),
348	            }
349	        }
350	    }
351	}
