448	pub struct ClaimStore {
449	    path: PathBuf,
450	}
451	
452	impl ClaimStore {
453	    pub fn new(path: impl Into<PathBuf>) -> Self {
454	        Self { path: path.into() }
455	    }
456	
457	    fn load_all(&self) -> Vec<ClaimData> {
458	        match fs::read_to_string(&self.path) {
459	            Ok(contents) => serde_json::from_str(&contents)
460	                .expect("Failed to parse claims file - data corrupted"),
461	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Vec::new(),
462	            Err(e) => panic!("Failed to read claims file: {}", e),
463	        }
464	    }
465	
466	    fn save_all(&self, claims: &[ClaimData]) {
467	        if let Some(parent) = self.path.parent() {
468	            fs::create_dir_all(parent).expect("Failed to create claims directory");
469	        }
470	        let contents = serde_json::to_string_pretty(claims).expect("Failed to serialize claims");
471	        fs::write(&self.path, contents).expect("Failed to write claims file");
472	    }
473	
474	    pub fn store(&self, claim: ClaimData) {
475	        let mut claims = self.load_all();
476	        let existing = claims.iter().filter(|c| c.epoch == claim.epoch).count();
477	        if existing > 0 {
478	            panic!(
479	                "Duplicate claim for epoch {} - this should never happen",
480	                claim.epoch
481	            );
482	        }
483	        claims.push(claim);
484	        self.save_all(&claims);
485	    }
486	
487	    pub fn update<F>(&self, epoch: u64, f: F)
488	    where
489	        F: FnOnce(&mut ClaimData),
490	    {
491	        let mut claims = self.load_all();
492	        let claim = claims.iter_mut().find(|c| c.epoch == epoch);
493	        match claim {
494	            Some(c) => {
495	                f(c);
496	                self.save_all(&claims);
497	            }
498	            None => panic!("Cannot update claim for epoch {} - not found", epoch),
499	        }
500	    }
501	
502	    pub fn get(&self, epoch: u64) -> ClaimData {
503	        let claims = self.load_all();
504	        let matches: Vec<_> = claims.into_iter().filter(|c| c.epoch == epoch).collect();
505	        match matches.len() {
506	            0 => panic!("No claim found for epoch {}", epoch),
507	            1 => matches.into_iter().next().unwrap(),
508	            n => panic!(
509	                "Multiple claims ({}) for epoch {} - impossible state",
510	                n, epoch
511	            ),
512	        }
513	    }
514	
515	    pub fn get_claim(&self, epoch: u64) -> Claim {
516	        let c = self.get(epoch);
517	        Claim {
518	            stateRoot: c.state_root,
519	            claimer: c.claimer,
520	            timestampClaimed: c.timestamp_claimed,
521	            timestampVerification: c.timestamp_verification,
522	            blocknumberVerification: c.blocknumber_verification,
523	            honest: match c.honest.as_str() {
524	                "Claimer" => Party::Claimer,
525	                "Challenger" => Party::Challenger,
526	                _ => Party::None,
527	            },
528	            challenger: c.challenger,
529	        }
530	    }
531	
532	    pub fn remove(&self, epoch: u64) {
533	        let mut claims = self.load_all();
534	        claims.retain(|c| c.epoch != epoch);
535	        self.save_all(&claims);
536	    }
537	
538	    pub fn has_state_root_in_recent_claims(
539	        &self,
540	        state_root: FixedBytes<32>,
541	        since_timestamp: u32,
542	    ) -> bool {
543	        let claims = self.load_all();
544	        claims
545	            .iter()
546	            .any(|c| c.state_root == state_root && c.timestamp_claimed >= since_timestamp)
547	    }
548	
549	    pub fn exists(&self, epoch: u64) -> bool {
