73	            let response = fut.await?;
74	
75	            let infra_error = match &response {
76	                ResponsePacket::Single(r) => match &r.payload {
77	                    ResponsePayload::Failure(e) if is_infra_rpc_error(e.code, &e.message) => {
78	                        Some(format!("error code {}: {}", e.code, e.message))
79	                    }
80	                    _ => None,
81	                },
82	                ResponsePacket::Batch(rs) => rs.iter().find_map(|r| match &r.payload {
83	                    ResponsePayload::Failure(e) if is_infra_rpc_error(e.code, &e.message) => {
84	                        Some(format!("error code {}: {}", e.code, e.message))
85	                    }
86	                    _ => None,
87	                }),
88	            };
89	
90	            if let Some(msg) = infra_error {
91	                warn!(
92	                    logger = "Config",
93	                    transport = label.as_str(),
94	                    "RPC endpoint returned infra-level error, treating as unavailable for fallback purposes: {msg}"
95	                );
96	                return Err(TransportErrorKind::custom_str(&msg));
97	            }
98	
99	            Ok(response)
100	        })
101	    }
102	}
