159	/// Strips path/query from an RPC URL so it's safe to log (RPC URLs commonly embed
160	/// API keys in the path, e.g. `https://rpc.ankr.com/eth_sepolia/<key>`).
161	fn redact_url(url: &str) -> String {
162	    match url.split_once("://") {
163	        Some((scheme, rest)) => {
164	            // Secrets can appear in the path (`/eth_sepolia/<key>`), the query string
165	            // (`?apikey=<key>`), or userinfo (`user:pass@host`) - strip all three.
166	            let host_and_after = rest.split_once('@').map_or(rest, |(_, after)| after);
167	            let host = host_and_after
168	                .split(['/', '?', '#'])
169	                .next()
170	                .unwrap_or(host_and_after);
171	            format!("{scheme}://{host}")
172	        }
173	        None => "unknown".to_string(),
174	    }
175	}
