177	fn build_http_client() -> reqwest::Client {
178	    reqwest::Client::builder()
179	        .connect_timeout(Duration::from_secs(10))
180	        .timeout(RPC_TIMEOUT)
181	        .build()
182	        .expect("Failed to build HTTP client")
183	}
