185	fn build_provider_from_urls(urls: &[String], wallet: &EthereumWallet) -> DynProvider<Ethereum> {
186	    let http_client = build_http_client();
187	
188	    if urls.len() == 1 {
189	        let transport = Http::with_client(http_client, urls[0].parse().expect("Invalid RPC URL"));
190	        let client = RpcClient::builder().transport(transport, false);
191	        return DynProvider::new(
192	            ProviderBuilder::new()
193	                .wallet(wallet.clone())
194	                .connect_client(client),
195	        );
196	    }
197	
198	    let fallback =
199	        FallbackLayer::default().with_active_transport_count(NonZeroUsize::new(3).unwrap());
200	
201	    let transports: Vec<_> = urls
202	        .iter()
203	        .map(|url| ErrorAwareTransport {
204	            inner: Http::with_client(http_client.clone(), url.parse().expect("Invalid RPC URL")),
205	            label: redact_url(url),
206	        })
207	        .collect();
208	
209	    let transport = ServiceBuilder::new().layer(fallback).service(transports);
210	
211	    let client = RpcClient::builder().transport(transport, false);
212	    DynProvider::new(
213	        ProviderBuilder::new()
214	            .wallet(wallet.clone())
215	            .connect_client(client),
216	    )
217	}
