17	const RETRY_DELAY_SECS: u64 = 5 * 60;
18	
19	async fn run_route_with_retry(config: ValidatorConfig, route: Route) {
20	    loop {
21	        let result = AssertUnwindSafe(run_route(config.clone(), route.clone()))
22	            .catch_unwind()
23	            .await;
24	
25	        match result {
26	            Ok(()) => break,
27	            Err(e) => {
28	                let msg = if let Some(s) = e.downcast_ref::<&str>() {
29	                    s.to_string()
30	                } else if let Some(s) = e.downcast_ref::<String>() {
31	                    s.clone()
32	                } else {
33	                    "unknown panic".to_string()
34	                };
35	                error!(
36	                    logger = "Main",
37	                    route = route.name,
38	                    delay_secs = RETRY_DELAY_SECS,
39	                    "Route crashed: {msg}. Retrying..."
40	                );
41	                sleep(Duration::from_secs(RETRY_DELAY_SECS)).await;
42	            }
43	        }
44	    }
45	}
