47	async fn run_route(config: ValidatorConfig, route: Route) {
48	    let name = route.name.to_lowercase().replace("_", "-");
49	    let schedule_path = format!("data/schedules/{}.json", name);
50	    let claims_path = format!("data/claims/{}.json", name);
51	
52	    let inbox = IVeaInbox::new(route.inbox_address, route.inbox_provider.clone());
53	    let epoch_period: u64 = inbox
54	        .epochPeriod()
55	        .call()
56	        .await
57	        .expect("Failed to get epochPeriod")
58	        .try_into()
59	        .expect("epochPeriod overflow");
60	
61	    info!(logger = "Main", route = route.name, inbox = ?route.inbox_address, outbox = ?route.outbox_address, epoch_period, "Route initialized");
62	
63	    let task_store = Arc::new(Mutex::new(TaskStore::new(&schedule_path)));
64	    let claim_store = Arc::new(Mutex::new(ClaimStore::new(&claims_path)));
65	
66	    let wallet_address = config.wallet.default_signer().address();
67	    let watcher = EpochWatcher::new(
68	        config.clone(),
69	        route.clone(),
70	        config.make_claims,
71	        claim_store.clone(),
72	        task_store.clone(),
73	    );
74	    let indexer = EventIndexer::new(
75	        route.clone(),
76	        wallet_address,
77	        task_store.clone(),
78	        claim_store.clone(),
79	    );
80	    let dispatcher = TaskDispatcher::new(
81	        config,
82	        route.clone(),
83	        task_store.clone(),
84	        claim_store.clone(),
85	    );
86	
87	    indexer.initialize().await;
88	
89	    tokio::select! {
90	        r = watcher.watch_epochs(epoch_period) => {
91	            panic!("[{}] Epoch watcher died: {:?}", route.name, r);
92	        }
93	        _ = indexer.run() => {
94	            panic!("[{}] Indexer died unexpectedly", route.name);
95	        }
96	        _ = dispatcher.run() => {
97	            panic!("[{}] Dispatcher died unexpectedly", route.name);
98	        }
99	    }
100	}
