102	#[tokio::main]
103	async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
104	    tracing_subscriber::fmt()
105	        .json()
106	        .flatten_event(true)
107	        .with_target(false)
108	        .with_env_filter(
109	            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
110	        )
111	        .init();
112	
113	    std::panic::set_hook(Box::new(|info| {
114	        let msg = if let Some(s) = info.payload().downcast_ref::<&str>() {
115	            s.to_string()
116	        } else if let Some(s) = info.payload().downcast_ref::<String>() {
117	            s.clone()
118	        } else {
119	            "unknown panic".to_string()
120	        };
121	        tracing::error!(logger = "Panic", "{msg}");
122	    }));
123	
124	    let c = ValidatorConfig::from_env()?;
125	    info!(logger = "Main", address = %c.wallet.default_signer().address(), "Validator started");
126	
127	    let mut routes = c.build_routes();
128	    check_rpc_health(&routes).await?;
129	    check_balances(&c, &routes).await?;
130	    check_finality_config(&c);
131	
132	    let eth_provider = routes[0].outbox_provider.clone();
133	    for route in routes.iter_mut() {
134	        route.settings = load_route_settings(route, c.arb_outbox, &eth_provider).await;
135	    }
136	
137	    info!(
138	        logger = "Main",
139	        route_count = routes.len(),
140	        "Starting validator"
141	    );
142	
143	    let handles: Vec<_> = routes
144	        .into_iter()
145	        .map(|route| {
146	            let config = c.clone();
147	            tokio::spawn(run_route_with_retry(config, route))
148	        })
149	        .collect();
150	
151	    tokio::select! {
152	        _ = select_all(handles) => {}
153	        _ = tokio::signal::ctrl_c() => {
154	            info!(logger = "Main", "Shutting down");
155	        }
156	    }
157	
158	    Ok(())
159	}
